@Composable
fun CounterContent(count: Int, onIncrement: () -> Unit) {
    Button(onClick = onIncrement) { Text("Clicked $count times") }   // stateless and easy to preview
}

data class CounterState(val count: Int = 0, val loading: Boolean = false)

sealed interface CounterIntent {
    data object Increment : CounterIntent
    data object Reset : CounterIntent
}

fun reduce(state: CounterState, intent: CounterIntent): CounterState = when (intent) {
    CounterIntent.Increment -> state.copy(count = state.count + 1)
    CounterIntent.Reset -> state.copy(count = 0)
}

class CounterViewModel : ViewModel() {
    private val _state = MutableStateFlow(CounterState())
    val state = _state.asStateFlow()

    fun onIntent(intent: CounterIntent) = _state.update { reduce(it, intent) }
}

data class HomeState(
    val user: User? = null,
    val orders: List<Order> = emptyList(),
    val isRefreshing: Boolean = false
)

class HomeViewModel(users: UserRepository, orders: OrderRepository) : ViewModel() {
    private val refreshing = MutableStateFlow(false)

    val state: StateFlow<HomeState> = combine(
        users.observeUser(), orders.observeOrders(), refreshing
    ) { user, orderList, isRefreshing ->
        HomeState(user, orderList, isRefreshing)          // one consistent snapshot
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), HomeState())
}

